CREATE TABLE "ForecastScenario" ("id" TEXT NOT NULL,"ventureId" TEXT NOT NULL,"name" TEXT NOT NULL,"months" INTEGER NOT NULL DEFAULT 12,"revenueGrowth" DOUBLE PRECISION NOT NULL,"costGrowth" DOUBLE PRECISION NOT NULL,"volatility" DOUBLE PRECISION NOT NULL DEFAULT 0.10,"simulations" INTEGER NOT NULL DEFAULT 1000,"seed" INTEGER NOT NULL DEFAULT 872,"result" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ForecastScenario_pkey" PRIMARY KEY ("id"),CONSTRAINT "ForecastScenario_ventureId_fkey" FOREIGN KEY ("ventureId") REFERENCES "Venture"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "ForecastScenario_ventureId_createdAt_idx" ON "ForecastScenario"("ventureId","createdAt");
CREATE TABLE "FinancialBenchmark" ("id" TEXT NOT NULL,"ventureId" TEXT NOT NULL,"metric" TEXT NOT NULL,"value" DOUBLE PRECISION NOT NULL,"unit" TEXT NOT NULL,"cohort" TEXT,"sourceName" TEXT NOT NULL,"sourceUrl" TEXT,"observedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "FinancialBenchmark_pkey" PRIMARY KEY ("id"),CONSTRAINT "FinancialBenchmark_ventureId_fkey" FOREIGN KEY ("ventureId") REFERENCES "Venture"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "FinancialBenchmark_ventureId_metric_idx" ON "FinancialBenchmark"("ventureId","metric"); CREATE INDEX "FinancialBenchmark_sourceName_idx" ON "FinancialBenchmark"("sourceName");
CREATE TABLE "IoTFinancialSignal" ("id" TEXT NOT NULL,"ventureId" TEXT NOT NULL,"metric" TEXT NOT NULL,"value" DOUBLE PRECISION NOT NULL,"unit" TEXT NOT NULL,"financialMetric" TEXT,"conversionRate" DOUBLE PRECISION,"source" TEXT NOT NULL,"observedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "IoTFinancialSignal_pkey" PRIMARY KEY ("id"),CONSTRAINT "IoTFinancialSignal_ventureId_fkey" FOREIGN KEY ("ventureId") REFERENCES "Venture"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE INDEX "IoTFinancialSignal_ventureId_metric_observedAt_idx" ON "IoTFinancialSignal"("ventureId","metric","observedAt"); CREATE INDEX "IoTFinancialSignal_financialMetric_idx" ON "IoTFinancialSignal"("financialMetric");